<script lang="ts">
 import {bulkEnrichProgress,enrichAllBookmarks,LOCAL_LINK_PREVIEWS_KEY} from '../../lib/enrich'; import {connected,items,userSettings,updateUserSettings} from '../../lib/stores'; import {needsEnrichment} from '../../lib/enrich'; import {showToast} from '../../lib/toast';
 const read=(k:string)=>{try{return localStorage.getItem(k)}catch{return null}}; const write=(k:string,v:string)=>{try{localStorage.setItem(k,v)}catch{}}; let localOn=$state(read(LOCAL_LINK_PREVIEWS_KEY)!=='false'); const on=$derived($userSettings.linkPreviews!==false&&localOn); const missing=$derived(Object.values($items).filter(i=>i.type==='bookmark'&&needsEnrichment(i)).length); const total=$derived(Object.values($items).filter(i=>i.type==='bookmark').length);
 function toggle(v:boolean){localOn=v;write(LOCAL_LINK_PREVIEWS_KEY,String(v));if($connected)void updateUserSettings({linkPreviews:v?undefined:false})} function fetchAll(){void enrichAllBookmarks().then(r=>r&&showToast(`Updated ${r.updated} of ${r.total} bookmarks`)).catch(()=>showToast('Failed to fetch link previews'))}
</script>
<div class="settings-section"><div class="row"><div class="row-main"><div class="row-label">Show previews for saved links</div><div class="row-desc">Fetched via <a href="https://sockethub.org" target="_blank" rel="noreferrer">Sockethub</a>'s <code>metadata</code> platform — the page title, description and image, without your browser ever contacting the site. Configure the relay in Settings → Account.</div></div><div class="row-ctl"><button type="button" class="switch" class:on aria-label="Show previews for saved links" aria-pressed={on} onclick={()=>toggle(!on)}></button></div></div>
{#if on}<div class="row"><div class="row-main"><div class="row-label">Fill in older bookmarks</div><div class="row-desc">{missing} of {total} saved links have no preview yet.</div></div><div class="row-ctl"><button class="btn" type="button" disabled={!missing||!!$bulkEnrichProgress} onclick={fetchAll}>{$bulkEnrichProgress?`${$bulkEnrichProgress.done}/${$bulkEnrichProgress.total}`:`Fetch ${missing} previews`}</button></div></div>{/if}</div>
